 1→import { inject, Injectable } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { NoteDataService } from './note-data.service';
 4→
 5→const MAX_FRET = 15;
 6→
 7→@Injectable()
 8→export class ProgressionService {
 9→  private readonly noteDataService = inject(NoteDataService);
10→
11→  private currentFret = 0;
12→  private pool: FretNote[] = [];
13→  private shownNoteKeys = new Set<string>();
14→
15→  constructor() {
16→    this.pool = this.noteDataService.getNotesOnFret(0);
17→  }
18→
19→  getCurrentPool(): FretNote[] {
20→    return this.pool;
21→  }
22→
23→  getCurrentFret(): number {
24→    return this.currentFret;
25→  }
26→
27→  getShownNoteCount(): number {
28→    return this.shownNoteKeys.size;
29→  }
30→
31→  getRandomNote(): FretNote {
32→    if (this.pool.length === 0) {
33→      throw new Error('ProgressionService: pool is empty — cannot get random note');
34→    }
35→    const index = Math.floor(Math.random() * this.pool.length);
36→    return this.pool[index];
37→  }
38→
39→  markNoteAsShown(note: FretNote): void {
40→    this.shownNoteKeys.add(this.noteKey(note));
41→
42→    if (this.shownNoteKeys.size >= this.pool.length) {
43→      this.expandPool();
44→    }
45→  }
46→
47→  reset(): void {
48→    this.currentFret = 0;
49→    this.pool = this.noteDataService.getNotesOnFret(0);
50→    this.shownNoteKeys.clear();
51→  }
52→
53→  private expandPool(): void {
54→    let nextFret = this.currentFret + 1;
55→
56→    while (nextFret <= MAX_FRET) {
57→      const newNotes = this.noteDataService.getNotesOnFret(nextFret);
58→      if (newNotes.length > 0) {
59→        this.currentFret = nextFret;
60→        this.pool = this.noteDataService.getNotesUpToFret(nextFret);
61→        this.shownNoteKeys.clear();
62→        return;
63→      }
64→      nextFret++;
65→    }
66→
67→    // Already at max — no expansion possible
68→  }
69→
70→  private noteKey(note: FretNote): string {
71→    return `${note.string}-${note.fret}`;
72→  }
73→}
