  1→import { TestBed } from '@angular/core/testing';
  2→import { ProgressionService } from './progression.service';
  3→import { NoteDataService } from './note-data.service';
  4→import { FretNote } from './note-data';
  5→
  6→describe('ProgressionService', () => {
  7→  let service: ProgressionService;
  8→  let noteDataService: NoteDataService;
  9→
 10→  beforeEach(() => {
 11→    TestBed.configureTestingModule({
 12→      providers: [ProgressionService, NoteDataService],
 13→    });
 14→    service = TestBed.inject(ProgressionService);
 15→    noteDataService = TestBed.inject(NoteDataService);
 16→  });
 17→
 18→  describe('initial state', () => {
 19→    it('should start with open strings (fret 0) as the current pool', () => {
 20→      const pool = service.getCurrentPool();
 21→
 22→      expect(pool.length).toBe(6);
 23→      for (const note of pool) {
 24→        expect(note.fret).toBe(0);
 25→      }
 26→    });
 27→
 28→    it('should match the open string notes from NoteDataService', () => {
 29→      const pool = service.getCurrentPool();
 30→      const expected = noteDataService.getNotesOnFret(0);
 31→
 32→      expect(pool).toEqual(expected);
 33→    });
 34→
 35→    it('should start at fret level 0', () => {
 36→      expect(service.getCurrentFret()).toBe(0);
 37→    });
 38→
 39→    it('should have no shown notes initially', () => {
 40→      expect(service.getShownNoteCount()).toBe(0);
 41→    });
 42→  });
 43→
 44→  describe('getRandomNote', () => {
 45→    it('should return a note from the current pool', () => {
 46→      const pool = service.getCurrentPool();
 47→      const note = service.getRandomNote();
 48→
 49→      expect(pool).toContain(note);
 50→    });
 51→
 52→    it('should throw an error when the pool is empty', () => {
 53→      // Access private pool via any-cast to force an empty pool scenario
 54→      (service as any).pool = [];
 55→
 56→      expect(() => service.getRandomNote()).toThrowError(
 57→        'ProgressionService: pool is empty — cannot get random note',
 58→      );
 59→    });
 60→
 61→    it('should return different notes over multiple calls (statistical check)', () => {
 62→      const notes = new Set<string>();
 63→      for (let i = 0; i < 50; i++) {
 64→        const note = service.getRandomNote();
 65→        notes.add(`${note.string}-${note.fret}`);
 66→      }
 67→      // With 6 open strings and 50 draws, we should see more than 1 unique note
 68→      expect(notes.size).toBeGreaterThan(1);
 69→    });
 70→  });
 71→
 72→  describe('markNoteAsShown', () => {
 73→    it('should track that a note has been shown', () => {
 74→      const note = service.getRandomNote();
 75→      service.markNoteAsShown(note);
 76→
 77→      expect(service.getShownNoteCount()).toBe(1);
 78→    });
 79→
 80→    it('should not double-count the same note shown twice', () => {
 81→      const pool = service.getCurrentPool();
 82→      const note = pool[0];
 83→
 84→      service.markNoteAsShown(note);
 85→      service.markNoteAsShown(note);
 86→
 87→      expect(service.getShownNoteCount()).toBe(1);
 88→    });
 89→
 90→    it('should count distinct notes that have been shown', () => {
 91→      const pool = service.getCurrentPool();
 92→
 93→      service.markNoteAsShown(pool[0]);
 94→      service.markNoteAsShown(pool[1]);
 95→      service.markNoteAsShown(pool[2]);
 96→
 97→      expect(service.getShownNoteCount()).toBe(3);
 98→    });
 99→  });
100→
101→  describe('pool expansion', () => {
102→    it('should expand pool when all current notes have been shown', () => {
103→      const openStrings = service.getCurrentPool();
104→      expect(openStrings.length).toBe(6);
105→
106→      // Mark all open string notes as shown
107→      for (const note of openStrings) {
108→        service.markNoteAsShown(note);
109→      }
110→
111→      // Pool should now include fret 1 notes too
112→      const expandedPool = service.getCurrentPool();
113→      const fret1Notes = noteDataService.getNotesOnFret(1);
114→
115→      expect(expandedPool.length).toBe(openStrings.length + fret1Notes.length);
116→      expect(service.getCurrentFret()).toBe(1);
117→    });
118→
119→    it('should keep previously learned notes in the expanded pool', () => {
120→      const openStrings = [...service.getCurrentPool()];
121→
122→      // Mark all open string notes as shown
123→      for (const note of openStrings) {
124→        service.markNoteAsShown(note);
125→      }
126→
127→      const expandedPool = service.getCurrentPool();
128→      for (const openNote of openStrings) {
129→        expect(expandedPool).toContain(openNote);
130→      }
131→    });
132→
133→    it('should reset shown tracking after expansion', () => {
134→      const openStrings = service.getCurrentPool();
135→
136→      // Mark all as shown to trigger expansion
137→      for (const note of openStrings) {
138→        service.markNoteAsShown(note);
139→      }
140→
141→      // After expansion, shown count should reset to 0
142→      expect(service.getShownNoteCount()).toBe(0);
143→    });
144→
145→    it('should expand through multiple frets sequentially', () => {
146→      // Expand through frets 0, 1, 2
147→      for (let targetFret = 1; targetFret <= 2; targetFret++) {
148→        const currentPool = service.getCurrentPool();
149→        for (const note of currentPool) {
150→          service.markNoteAsShown(note);
151→        }
152→        expect(service.getCurrentFret()).toBe(targetFret);
153→      }
154→
155→      const finalPool = service.getCurrentPool();
156→      const expectedNotes = noteDataService.getNotesUpToFret(2);
157→      expect(finalPool.length).toBe(expectedNotes.length);
158→    });
159→
160→    it('should skip frets that have no natural notes', () => {
161→      // Fret 11 has no natural notes. When expanding from fret 10,
162→      // it should skip to fret 12.
163→      // First, fast-forward to fret 10
164→      for (let targetFret = 1; targetFret <= 10; targetFret++) {
165→        const currentPool = service.getCurrentPool();
166→        for (const note of currentPool) {
167→          service.markNoteAsShown(note);
168→        }
169→      }
170→
171→      expect(service.getCurrentFret()).toBe(10);
172→
173→      // Now mark all current pool notes as shown
174→      const poolAtFret10 = service.getCurrentPool();
175→      for (const note of poolAtFret10) {
176→        service.markNoteAsShown(note);
177→      }
178→
179→      // Should have skipped fret 11 (no natural notes) and gone to fret 12
180→      expect(service.getCurrentFret()).toBe(12);
181→    });
182→
183→    it('should not expand beyond fret 15', () => {
184→      // Fast-forward to max fret
185→      for (let targetFret = 1; targetFret <= 15; targetFret++) {
186→        const currentPool = service.getCurrentPool();
187→        for (const note of currentPool) {
188→          service.markNoteAsShown(note);
189→        }
190→      }
191→
192→      // We should be at fret 15 (or less if some frets were skipped)
193→      const currentFret = service.getCurrentFret();
194→      expect(currentFret).toBeLessThanOrEqual(15);
195→
196→      // Mark all notes as shown again — should NOT crash or go beyond 15
197→      const finalPool = service.getCurrentPool();
198→      for (const note of finalPool) {
199→        service.markNoteAsShown(note);
200→      }
201→
202→      expect(service.getCurrentFret()).toBeLessThanOrEqual(15);
203→      // Pool should contain all natural notes
204→      expect(service.getCurrentPool().length).toBe(noteDataService.getNotesUpToFret(15).length);
205→    });
206→  });
207→
208→  describe('reset', () => {
209→    it('should reset to initial state with open strings only', () => {
210→      // Expand pool first
211→      const openStrings = service.getCurrentPool();
212→      for (const note of openStrings) {
213→        service.markNoteAsShown(note);
214→      }
215→
216→      service.reset();
217→
218→      expect(service.getCurrentFret()).toBe(0);
219→      expect(service.getCurrentPool().length).toBe(6);
220→      expect(service.getShownNoteCount()).toBe(0);
221→    });
222→  });
223→});
